public String pyramid(int n) {
    StringBuilder sb = new StringBuilder();
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s < n - i; s++) sb.append(' ');
        for (int j = 0; j < 2 * i - 1; j++) sb.append('*');
        if (i < n) sb.append('\n');
    }
    return sb.toString();
}

